const labels = Object.fromEntries(Object.entries(raw).map(([k, v]) => [P + k, v]));
const pick = (i) => Object.fromEntries(Object.entries(labels).map(([key, values]) => [key, values[i]]));
export const workflowBuilderTranslations = { en: pick(0), de: pick(1), fr: pick(2), ar: pick(3) };
export default workflowBuilderTranslations;
